Here are some practical code examples demonstrating multi-tenant SaaS deployment patterns:

## 1. Serverless Function (Python/AWS Lambda)

```python
import json
import boto3
from datetime import datetime
from typing import Dict, Any

class MultiTenantSaaSService:
    """Multi-tenant SaaS service with tenant isolation"""

    def __init__(self):
        self.dynamodb = boto3.resource('dynamodb')
        self.sqs = boto3.client('sqs')

    def process_request(self, event: Dict[str, Any]) -> Dict[str, Any]:
        """Process incoming request with tenant isolation"""
        tenant_id = event.get('tenant_id', 'default')

        # Validate tenant context
        if not self._validate_tenant_context(tenant_id):
            return {
                'statusCode': 403,
                'body': json.dumps({'error': 'Unauthorized access'})
            }

        # Process business logic
        result = self._execute_business_logic(event)

        # Log to CloudWatch with tenant context
        self._log_with_tenant_context(tenant_id, result)

        return {
            'statusCode': 200,
            'body': json.dumps(result)
        }

    def _validate_tenant_context(self, tenant_id: str) -> bool:
        """Validate tenant context for security"""
        # Implement proper tenant isolation checks
        pass

    def _execute_business_logic(self, event: Dict[str, Any]) -> Dict[str, Any]:
        """Execute business logic with tenant-scoped data"""
        return {'status': 'processed', 'timestamp': datetime.utcnow().isoformat()}

    def _log_with_tenant_context(self, tenant_id: str, result: Dict) -> None:
        """Log with tenant context for audit trail"""
        pass

# Lambda handler
def lambda_handler(event, context):
    service = MultiTenantSaaSService()
    return service.process_request(event)
```

## 2. Terraform Infrastructure (Multi-Tenant Setup)

```hcl
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

variable "tenant_id" {
  description = "Tenant identifier for isolation"
  type        = string
}

variable "environment" {
  description = "Deployment environment"
  type        = string
  default     = "production"
}

# VPC with tenant-specific networking
resource "aws_vpc" "tenant_vpc" {
  cidr_block           = var.tenant_id == "default" ? "10.0.0.0/16" : "10.${var.tenant_id}.0.0/16"
  enable_dns_hostnames = true

  tags = {
    Name        = "${var.environment}-vpc-${var.tenant_id}"
    Environment = var.environment
    Tenant      = var.tenant_id
  }
}

# Private subnets for application tier
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.tenant_vpc.id
  cidr_block        = cidrsubnet(aws_vpc.tenant_vpc.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.environment}-private-subnet-${count.index}"
  }
}

# RDS with tenant isolation
resource "aws_db_instance" "tenant_database" {
  identifier           = "${var.tenant_id}-db"
  engine               = "aurora-mysql"
  engine_version       = "5.7"
  instance_class       = "db.r6g.large"
  db_name              = var.tenant_id

  # Tenant-specific security
  vpc_security_group_ids

